def _ensure_dir(path):
	if not path:return
	if not os.path.isdir(path):os.makedirs(path)
def _module_path(root,name,is_pkg):
	parts=name.split('.')
	if is_pkg:parts.append('__init__.py')
	else:parts[-1]=parts[-1]+'.py'
	return os.path.join(root,*parts)
def _bootstrap_root():
	root=os.environ.get('SFB_FLAT_ROOT')
	if root:root=os.path.abspath(root);_ensure_dir(root);return root
	return tempfile.mkdtemp(prefix='sfb_flat_')
def _prepare_root(root,modules):
	for(name,is_pkg,_)in modules:path=_module_path(root,name,is_pkg);_ensure_dir(os.path.dirname(path))
def _load_modules(root,modules):
	for(name,is_pkg,_)in modules:
		mod=types.ModuleType(name);mod.__file__=_module_path(root,name,is_pkg)
		if is_pkg:mod.__package__=name;mod.__path__=[os.path.dirname(mod.__file__)]
		else:mod.__package__=name.rsplit('.',1)[0]if'.'in name else''
