def _run_entry(entry_spec):
	A=None;module_name,func_name=entry_spec.split(':',1);mod=sys.modules.get(module_name)
	if mod is A:raise SystemExit('entry module not loaded: %s'%module_name)
	func=getattr(mod,func_name,A)
	if func is A:raise SystemExit('entry function not found: %s'%entry_spec)
	return func()
def main():
	root=_bootstrap_root();_prepare_root(root,_MODULES);_load_modules(root,_MODULES);result=_run_entry(_ENTRY)
	if isinstance(result,int):return result
	return 0
if __name__=='__main__':sys.exit(main())